buggyCode:
// Trước refactor
Map<String, Product> bySku = new HashMap<>();
for (Product product : supplierFeed.read()) {
    bySku.put(product.sku(), product);
}

// Sau refactor
Map<String, Product> bySku = supplierFeed.read().stream()
        .collect(Collectors.toMap(Product::sku, product -> product));

fix.code:
Map<String, Product> bySku = supplierFeed.read().stream()
        .collect(Collectors.toMap(
                Product::sku,
                product -> product,
                (earlier, later) -> later));    // giữ đúng quy tắc cũ: dòng sau thắng

// Characterization test khoá hành vi trước khi refactor
@Test
void laterRowWinsWhenSkuRepeats() {
    var feed = feedOf(
            new Product("SKU-1", "Áo"),
            new Product("SKU-2", "Mũ"),
            new Product("SKU-1", "Áo (mới)"));

    assertThat(sync.buildIndex(feed).get("SKU-1").name()).isEqualTo("Áo (mới)");
}
